const $ = id => document.getElementById(id);
const KEY = 'zeta-lernreise-v1';
let state = {lesson:0,solved:[]};
let persistent = true;
try { const saved = JSON.parse(localStorage.getItem(KEY)); if(saved && Number.isInteger(saved.lesson) && saved.lesson>=0 && saved.lesson<7 && Array.isArray(saved.solved)) state={lesson:saved.lesson,solved:[...new Set(saved.solved.filter(x=>/^([0-6])-([0-2])$/.test(x)))]}; } catch {persistent=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{persistent=false;} }
function progress(){ $('progress').value=state.solved.length; $('progressText').textContent=Math.round(state.solved.length/21*100)+' %'; $('status').textContent=state.solved.length===21?'Geschafft! Alle 21 Aufgaben gelöst.':`${state.solved.length} von 21 Aufgaben gelöst${persistent?' · lokal gespeichert':' · Speichern nicht verfügbar'}`; $('nav').innerHTML=lessons.map((l,i)=>`<button data-lesson="${i}" class="${i===state.lesson?'active':''}" ${i===state.lesson?'aria-current="step"':''}><span class="number">${[0,1,2].every(j=>state.solved.includes(i+'-'+j))?'✓':i+1}</span>${l.name}</button>`).join(''); $('nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.lesson=+b.dataset.lesson;save();render();}); }
function render(){ const l=lessons[state.lesson]; $('lessonCount').textContent=`LEKTION ${state.lesson+1} / 7`; $('eyebrow').textContent=`LEKTION ${String(state.lesson+1).padStart(2,'0')} · ${l.name.toUpperCase()}`; $('title').textContent=l.title;$('subtitle').textContent=l.sub;$('theory').innerHTML=l.body;$('labTitle').textContent=l.lab;$('prev').disabled=state.lesson===0;$('next').disabled=state.lesson===6;
 $('exercises').innerHTML=l.q.map((q,j)=>`<form class="exercise" data-q="${j}"><label for="answer${j}"><b>Aufgabe ${j+1}</b><p>${q[0]}</p></label><input id="answer${j}" inputmode="decimal" autocomplete="off" placeholder="Deine Antwort" aria-describedby="feedback${j}"><button type="submit">Antwort prüfen</button><div id="feedback${j}" class="feedback ${state.solved.includes(state.lesson+'-'+j)?'correct':''}" role="status">${state.solved.includes(state.lesson+'-'+j)?'✓ Bereits gelöst. '+q[3]:''}</div><details><summary>Ein Hinweis</summary>${q[2]}</details></form>`).join('');
 $('exercises').querySelectorAll('form').forEach(form=>form.onsubmit=e=>{e.preventDefault();const j=+form.dataset.q;const q=l.q[j];const raw=$('answer'+j).value.trim().replace(',','.').replace('−','-'); const value=Number(raw);const feedback=$('feedback'+j); const valid=/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(raw)&&Number.isFinite(value);const ok=valid&&Math.abs(value-q[1])<=(q[4]||1e-8);feedback.className='feedback'+(ok?' correct':'');feedback.textContent=ok?'✓ Richtig! '+q[3]:valid?'Noch nicht ganz. '+q[2]:'Bitte gib eine Zahl ein, zum Beispiel −2 oder 0,5.';if(ok&&!state.solved.includes(state.lesson+'-'+j)){state.solved.push(state.lesson+'-'+j);save();progress();}});
 setupLab(l.mode);progress(); }
const fmt=n=>Math.abs(n)<0.000005?'0':Number(n.toFixed(4)).toLocaleString('de-DE',{maximumFractionDigits:4});
const complex=(a,b)=>`${fmt(a)} ${b<0?'−':'+'} ${fmt(Math.abs(b))}i`;
function range(id,label,min,max,step,value){return `<label class="control" for="${id}"><span>${label}</span><input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${value}"><span id="${id}Val"></span></label>`;}
function setupLab(mode){let html='';if(mode==='plane'||mode==='rotate')html=range('a','Realteil a',-4,4,.25,3)+range('b','Imaginärteil b',-4,4,.25,2)+(mode==='rotate'?range('k','Potenzen von i',0,4,1,1):'');if(mode==='polar')html=range('r','Betrag r',0,4,.1,3)+range('phi','Winkel φ (°)',0,360,1,45);if(mode==='euler')html=range('phi','Winkel φ (°)',0,360,1,60);if(mode==='power')html=range('n','Basis n',1,10,1,2)+range('sigma','Realteil σ',.25,3,.05,1)+range('t','Imaginärteil t',0,12,.1,1);if(mode==='sum')html=range('sigma','Reelles s',1.1,4,.1,2)+range('N','Glieder N',3,200,1,30);if(mode==='zeros')html=range('height','Höhe T',15,50,1,35);$('controls').innerHTML=html;$('controls').querySelectorAll('input').forEach(e=>e.oninput=()=>draw(mode));draw(mode);}
function line(x1,y1,x2,y2,color='#dfe8eb',extra=''){return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" ${extra}/>`;}
function label(x,y,t){return `<text x="${x}" y="${y}">${t}</text>`;}
function draw(mode){const v={};$('controls').querySelectorAll('input').forEach(e=>{v[e.id]=+e.value;$(e.id+'Val').textContent=fmt(+e.value);});let svg='';let note='';let result='';
 if(mode==='sum'){let sum=0;const points=[];for(let n=1;n<=v.N;n++){sum+=n**(-v.sigma);points.push([35+(n-1)/Math.max(1,v.N-1)*450,sum]);} const rest=v.N**(1-v.sigma)/(v.sigma-1);const top=Math.max(2,sum*1.15);const y=x=>275-x/top*235;for(let j=0;j<=4;j++){const val=j*top/4;svg+=line(35,y(val),485,y(val))+label(2,y(val)+4,fmt(val));}svg+=`<polyline points="${points.map(([x,a])=>x+','+y(a)).join(' ')}" fill="none" stroke="#087d68" stroke-width="3"/>`;svg+=label(35,300,'1')+label(420,300,'N = '+v.N)+label(40,24,'Partialsumme Sₙ'); result=`S${v.N}(${fmt(v.sigma)}) ≈ ${fmt(sum)}`;note=`Endliche Summe, keine exakte ζ-Auswertung. Rest höchstens ${fmt(Math.ceil(rest*10000)/10000)} (aufgerundet). ${v.sigma===2?'Zum Vergleich: ζ(2) ≈ 1,644934.':''}`;
 } else if(mode==='zeros'){const x=s=>170+s*145,y=t=>275-t/v.height*245;svg+=`<rect x="170" y="25" width="145" height="250" fill="#e5f3ec"/>`;for(let s=-1;s<=2;s++)svg+=line(x(s),25,x(s),275)+label(x(s)-7,296,s);for(let t=0;t<=v.height;t+=10)svg+=line(25,y(t),485,y(t))+label(4,y(t)+4,t);svg+=line(x(.5),25,x(.5),275,'#087d68','stroke-dasharray="5 5"')+label(250,22,'σ = ½');const zeros=[14.134725,21.022040,25.010858,30.424876,32.935062,37.586178,40.918719,43.327073,48.005151,49.773832];zeros.filter(t=>t<=v.height).forEach(t=>{svg+=`<circle cx="${x(.5)}" cy="${y(t)}" r="4" fill="#087d68"/>`+label(x(.5)+12,y(t)+4,fmt(t));});svg+=label(462,296,'Re(s)')+label(8,19,'Im(s)');result=`${zeros.filter(t=>t<=v.height).length} bekannte Nullstellen mit 0 < t ≤ ${v.height}`;note='Vorgegebene gerundete Werte, keine Live-Nullstellensuche und kein Beweis. Nur die obere Halbebene ist dargestellt; zu jeder dieser Nullstellen gehört ihre komplex Konjugierte.';
 } else {let a,b,scale=28;const cx=260,cy=155;if(mode==='plane'||mode==='rotate'){a=v.a;b=v.b;}if(mode==='polar'){a=v.r*Math.cos(v.phi*Math.PI/180);b=v.r*Math.sin(v.phi*Math.PI/180);}if(mode==='euler'){a=Math.cos(v.phi*Math.PI/180);b=Math.sin(v.phi*Math.PI/180);scale=115;}if(mode==='power'){const len=v.n**(-v.sigma),angle=-v.t*Math.log(v.n);a=len*Math.cos(angle);b=len*Math.sin(angle);scale=115;}for(let j=-4;j<=4;j++){svg+=line(cx+j*scale,12,cx+j*scale,298)+line(15,cy+j*scale,505,cy+j*scale);if(j&&mode!=='euler'&&mode!=='power')svg+=label(cx+j*scale-4,cy+18,j)+label(cx+7,cy-j*scale+4,j);}svg+=line(15,cy,505,cy,'#839ba1')+line(cx,12,cx,298,'#839ba1')+label(475,cy-10,'Re')+label(cx+10,22,'Im');const vector=(x,y,color,dash='')=>line(cx,cy,cx+x*scale,cy-y*scale,color,`stroke-width="3" ${dash}`)+`<circle cx="${cx+x*scale}" cy="${cy-y*scale}" r="6" fill="${color}"/>`;if(mode==='euler'||mode==='polar')svg+=`<circle cx="${cx}" cy="${cy}" r="${(mode==='euler'?1:v.r)*scale}" fill="none" stroke="#aacabc" stroke-dasharray="4 4"/>`;svg+=vector(a,b,'#087d68');result='z = '+complex(a,b);if(mode==='rotate'){const angle=v.k*Math.PI/2;const c=a*Math.cos(angle)-b*Math.sin(angle),d=a*Math.sin(angle)+b*Math.cos(angle);svg+=vector(c,d,'#c27938','stroke-dasharray="7 3"');result=`i^${v.k} · z = ${complex(c,d)}`;note='Grün: ursprüngliche Zahl. Orange gestrichelt: Ergebnis der Drehung.';}if(mode==='plane')note=`|z| = ${fmt(Math.hypot(a,b))}. Verändere beide Koordinaten und beobachte den Punkt.`;if(mode==='polar')note=v.r===0?'Am Ursprung ist der Winkel nicht definiert.':`r = ${fmt(v.r)} · φ = ${fmt(v.phi*Math.PI/180)} rad`;if(mode==='euler')note=`φ = ${fmt(v.phi*Math.PI/180)} rad. Horizontal: cos φ. Vertikal: sin φ. Der Betrag bleibt 1.`;if(mode==='power'){result=`${v.n}^(−s) ≈ ${complex(a,b)}`;note=`Betrag ${fmt(v.n**(-v.sigma))}, Winkel ${fmt(-v.t*Math.log(v.n))} rad (ohne Reduktion modulo 2π).`;}}
 $('plot').innerHTML=svg;$('plot').setAttribute('aria-label',lessons[state.lesson].lab+'. '+result+'. '+note);$('result').textContent=result;$('plotNote').textContent=note;
}
$('prev').onclick=()=>{if(state.lesson>0){state.lesson--;save();render();window.scrollTo({top:0,behavior:'smooth'});}};
$('next').onclick=()=>{if(state.lesson<6){state.lesson++;save();render();window.scrollTo({top:0,behavior:'smooth'});}};
$('reset').onclick=()=>{if(confirm('Alle gelösten Aufgaben und deinen Fortschritt zurücksetzen?')){state={lesson:0,solved:[]};save();render();}};
render();

